-- The schema of a new MLsuite installation, one baseline in sections by area. An installation only
-- ever starts empty from here, and every later change is a migration of its own.
--
-- Conventions every table follows:
--   * One numeric id, generated by the database, is its primary key. Whatever else identifies a row
--     (a slug, a public id, an environment's key) is a unique key beside it.
--   * Whatever a person, a visitor, an API client or the platform creates names its author as
--     created_by_principal_id and when (created_at); what can change also names who changed it last
--     (updated_by_principal_id) and when (updated_at). Rows written in the same action as a parent
--     (a role's permissions, a snapshot's bindings, a run's results, a job's rows, a review's runs)
--     carry no author of their own.
--   * References that must stay within one organization, schema or snapshot are composite foreign
--     keys. A column a row carries only for such a key is copied from its parent by the code that
--     writes the row, and the key refuses any value that disagrees with the parent.
--   * What is written once is guarded: a trigger refuses an update that would change it.
--   * A principal is never deleted, so author columns need no index for their foreign keys; only
--     authors a query reads are indexed.
--   * Every constraint is named; the API tells a refused write apart by the constraint's name.

-- ================================================================================================
-- Accounts
-- ================================================================================================

CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- The guard of what is written once: its trigger names the constraint the refusal reports.
-- Every trigger's refusal ends as PostgreSQL's own check violations do ('violates check constraint
-- "name"'): Hibernate reads the constraint's name from that text, not from CONSTRAINT, and the API
-- answers a refusal by its constraint's name.
CREATE FUNCTION refuse_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION '% cannot change once written: violates check constraint "%"', TG_TABLE_NAME, TG_ARGV[0] USING ERRCODE = 'check_violation',
        CONSTRAINT = TG_ARGV[0], TABLE = TG_TABLE_NAME;
END $$;

-- Nothing new is written under an organization, schema or model a purge is deleting (its purging_at
-- is set): the trigger names the parent table and the column of the new row that points at it.
CREATE FUNCTION refuse_under_purge() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    closing BOOLEAN;
BEGIN
    EXECUTE format('SELECT purging_at IS NOT NULL FROM %I WHERE id = $1', TG_ARGV[0])
        INTO closing USING (to_jsonb(NEW) ->> TG_ARGV[1])::bigint;
    IF closing THEN
        RAISE EXCEPTION 'The % is being deleted: violates check constraint "ck_%_not_purging"', TG_ARGV[0], TG_TABLE_NAME USING ERRCODE = 'check_violation',
            CONSTRAINT = 'ck_' || TG_TABLE_NAME || '_not_purging', TABLE = TG_TABLE_NAME;
    END IF;
    RETURN NEW;
END $$;

-- People. An address belongs to one account whatever its case; usernames and organization slugs
-- share one handle namespace (a personal account's slug is its owner's username). A handle is
-- lowercase letters and digits in runs joined by single hyphens, so two spellings of one name never
-- coexist.
CREATE TABLE app_user (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_app_user PRIMARY KEY,
    username VARCHAR(39) NOT NULL CONSTRAINT uq_app_user_username UNIQUE
        CONSTRAINT ck_app_user_username_handle CHECK (username ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    email VARCHAR(100) NOT NULL,
    full_name VARCHAR(150) NOT NULL CONSTRAINT ck_app_user_full_name_present CHECK (btrim(full_name) <> ''),
    password_hash VARCHAR(255) NOT NULL,
    enabled BOOLEAN NOT NULL,
    system_role VARCHAR(32) NOT NULL CONSTRAINT ck_app_user_system_role CHECK (system_role IN ('USER', 'SUPERADMIN')),
    -- The organization the person works in now; an API preference, not authorization.
    current_organization_id BIGINT,
    -- What a person says about themselves on their profile, public unless they say otherwise.
    bio VARCHAR(280),
    location VARCHAR(100),
    website VARCHAR(255),
    company VARCHAR(100),
    profile_links VARCHAR(255)[] NOT NULL DEFAULT '{}' CONSTRAINT ck_app_user_profile_links CHECK (cardinality(profile_links) <= 4),
    profile_public BOOLEAN NOT NULL DEFAULT TRUE,
    profile_shows_organizations BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL);

CREATE UNIQUE INDEX uq_app_user_email_lower ON app_user (lower(email));

-- Whoever does something. A person's and a client's principal is written with their row and
-- outlives it: deleting the account cuts the link and labels the principal with what it was, so
-- what they authored keeps an author. A visitor is the random id the API issues in a browser cookie
-- on their first public run, kept only as its digest. The platform is one principal of its own.
CREATE TABLE principal (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_principal PRIMARY KEY,
    kind VARCHAR(16) NOT NULL CONSTRAINT ck_principal_kind CHECK (kind IN ('USER', 'VISITOR', 'API_CLIENT', 'SYSTEM')),
    user_id BIGINT CONSTRAINT uq_principal_user UNIQUE
        CONSTRAINT fk_principal_user REFERENCES app_user (id) ON DELETE SET NULL,
    -- The SHA-256 of the random id a visitor's cookie carries, as an API key's secret is kept.
    visitor_token_sha256 VARCHAR(64) CONSTRAINT uq_principal_visitor UNIQUE
        CONSTRAINT ck_principal_visitor_token CHECK (visitor_token_sha256 ~ '^[0-9a-f]{64}$'),
    -- References api_client, created with it under API access.
    api_client_id BIGINT CONSTRAINT uq_principal_api_client UNIQUE,
    -- What the principal is shown as once its account is gone.
    former_label VARCHAR(255),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at TIMESTAMPTZ,
    CONSTRAINT ck_principal_links CHECK ((user_id IS NULL OR kind = 'USER') AND (api_client_id IS NULL OR kind = 'API_CLIENT')
        AND ((visitor_token_sha256 IS NOT NULL) = (kind = 'VISITOR'))),
    CONSTRAINT ck_principal_label CHECK (kind IN ('VISITOR', 'SYSTEM') OR user_id IS NOT NULL OR api_client_id IS NOT NULL
        OR former_label IS NOT NULL),
    CONSTRAINT uq_principal_id_kind UNIQUE (id, kind));

CREATE UNIQUE INDEX uq_principal_system ON principal (kind) WHERE kind = 'SYSTEM';
INSERT INTO principal (kind, former_label) VALUES ('SYSTEM', 'MLsuite');

CREATE FUNCTION app_user_is_a_principal() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO principal (kind, user_id) VALUES ('USER', NEW.id);
    RETURN NEW;
END $$;
CREATE TRIGGER trg_app_user_principal AFTER INSERT ON app_user FOR EACH ROW EXECUTE FUNCTION app_user_is_a_principal();

CREATE FUNCTION app_user_leaves_its_principal() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE principal SET former_label = 'Deleted user' WHERE user_id = OLD.id;
    RETURN OLD;
END $$;
CREATE TRIGGER trg_app_user_principal_label BEFORE DELETE ON app_user FOR EACH ROW EXECUTE FUNCTION app_user_leaves_its_principal();

-- A person's avatar as it is served: already square and small (a 256-pixel PNG or JPEG). Its author is always its person.
CREATE TABLE user_avatar (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_user_avatar PRIMARY KEY,
    user_id BIGINT NOT NULL CONSTRAINT uq_user_avatar_user UNIQUE
        CONSTRAINT fk_user_avatar_user REFERENCES app_user (id) ON DELETE CASCADE,
    content BYTEA NOT NULL CONSTRAINT ck_user_avatar_content CHECK (octet_length(content) BETWEEN 1 AND 2097152),
    content_type VARCHAR(40) NOT NULL CONSTRAINT ck_user_avatar_content_type CHECK (content_type IN ('image/png', 'image/jpeg')),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL);

-- An organization owns everything else; a personal one is its owner's namespace. The calls its API
-- clients may make in a calendar month (UTC) are set by a superadmin; null follows the default.
CREATE TABLE organization (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_organization PRIMARY KEY,
    slug VARCHAR(39) NOT NULL CONSTRAINT uq_organization_slug UNIQUE
        CONSTRAINT ck_organization_slug_handle CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    name VARCHAR(150) NOT NULL CONSTRAINT ck_organization_name_present CHECK (btrim(name) <> ''),
    description VARCHAR(600),
    kind VARCHAR(16) NOT NULL DEFAULT 'TEAM' CONSTRAINT ck_organization_kind CHECK (kind IN ('PERSONAL', 'TEAM')),
    owner_user_id BIGINT CONSTRAINT fk_organization_owner_user REFERENCES app_user (id),
    api_monthly_call_limit INTEGER CONSTRAINT ck_organization_api_monthly_call_limit
        CHECK (api_monthly_call_limit IS NULL OR api_monthly_call_limit >= 0),
    -- Set under the organization's lock when a purge of it is asked for, and never cleared.
    purging_at TIMESTAMPTZ,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_organization_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_organization_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT ck_organization_personal_owner CHECK ((kind = 'PERSONAL') = (owner_user_id IS NOT NULL)));

-- Only a personal account has an owner (CHECK above), so a plain key says one per person.
CREATE UNIQUE INDEX uq_organization_personal_owner ON organization (owner_user_id);
CREATE INDEX idx_search_org_name_trgm ON organization USING GIN (lower(name) gin_trgm_ops);
CREATE INDEX idx_search_org_slug_trgm ON organization USING GIN (slug gin_trgm_ops);

ALTER TABLE app_user ADD CONSTRAINT fk_app_user_current_organization
    FOREIGN KEY (current_organization_id) REFERENCES organization (id) ON DELETE SET NULL;

-- An organization's logo as it is served, shown wherever the organization is named.
CREATE TABLE organization_logo (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_organization_logo PRIMARY KEY,
    organization_id BIGINT NOT NULL CONSTRAINT uq_organization_logo_organization UNIQUE
        CONSTRAINT fk_organization_logo_organization REFERENCES organization (id) ON DELETE CASCADE,
    content BYTEA NOT NULL CONSTRAINT ck_organization_logo_content CHECK (octet_length(content) BETWEEN 1 AND 2097152),
    content_type VARCHAR(40) NOT NULL CONSTRAINT ck_organization_logo_content_type CHECK (content_type IN ('image/png', 'image/jpeg')),
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_organization_logo_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_organization_logo_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL);

-- The one list of what a role may grant.
CREATE TABLE permission (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_permission PRIMARY KEY,
    key VARCHAR(80) NOT NULL CONSTRAINT uq_permission_key UNIQUE);

INSERT INTO permission (key) VALUES
    ('VIEW_WORKSPACE'), ('VIEW_ORGANIZATION'), ('EDIT_ORGANIZATION'), ('DELETE_ORGANIZATION'), ('TRANSFER_OWNERSHIP'),
    ('VIEW_MEMBERS'), ('INVITE_MEMBERS'), ('MANAGE_MEMBER_ROLES'), ('REMOVE_MEMBERS'), ('VIEW_INVITATIONS'),
    ('MANAGE_INVITATIONS'), ('VIEW_MODELS'), ('CREATE_MODELS'), ('EDIT_MODELS'), ('DELETE_MODELS'), ('RUN_PREDICTIONS'),
    ('EXPORT_PREDICTIONS'), ('PUBLISH_BOOKMARKS'), ('REVIEW'), ('MANAGE_REVIEWS'), ('VIEW_PLUGINS'), ('MANAGE_PLUGINS'),
    ('VIEW_AUDIT_LOG'), ('VIEW_API_ACCESS'), ('MANAGE_API_ACCESS');

-- An organization's roles; RoleSeedService gives every organization its system roles.
CREATE TABLE role_definition (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_role_definition PRIMARY KEY,
    organization_id BIGINT NOT NULL CONSTRAINT fk_role_org REFERENCES organization (id),
    system_key VARCHAR(64),
    name VARCHAR(120) NOT NULL CONSTRAINT ck_role_definition_name_present CHECK (btrim(name) <> ''),
    slug VARCHAR(120) NOT NULL CONSTRAINT ck_role_definition_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    description VARCHAR(600),
    locked BOOLEAN NOT NULL,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_role_definition_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_role_definition_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_role_org_slug UNIQUE (organization_id, slug),
    CONSTRAINT uq_role_definition_org_id UNIQUE (organization_id, id));

CREATE UNIQUE INDEX uq_role_org_system_key ON role_definition (organization_id, system_key) WHERE system_key IS NOT NULL;
-- A role's name is one role's in its organization, whatever its case (its slug follows the name).
CREATE UNIQUE INDEX uq_role_definition_org_name ON role_definition (organization_id, lower(name));

CREATE TABLE role_permission (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_role_permission PRIMARY KEY,
    role_definition_id BIGINT NOT NULL CONSTRAINT fk_role_permission_role REFERENCES role_definition (id) ON DELETE CASCADE,
    permission_key VARCHAR(80) NOT NULL CONSTRAINT fk_role_permission_permission REFERENCES permission (key),
    CONSTRAINT uq_role_permission UNIQUE (role_definition_id, permission_key));

-- The platform's catalog of starting points an organization copies a role from.
CREATE TABLE role_template (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_role_template PRIMARY KEY,
    category VARCHAR(80) NOT NULL,
    name VARCHAR(120) NOT NULL CONSTRAINT ck_role_template_name_present CHECK (btrim(name) <> ''),
    slug VARCHAR(120) NOT NULL CONSTRAINT uq_role_template_slug UNIQUE CONSTRAINT ck_role_template_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    description VARCHAR(600),
    locked BOOLEAN NOT NULL,
    created_at TIMESTAMPTZ NOT NULL);

CREATE TABLE role_template_permission (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_role_template_permission PRIMARY KEY,
    role_template_id BIGINT NOT NULL CONSTRAINT fk_role_template_permission_template REFERENCES role_template (id)
        ON DELETE CASCADE,
    permission_key VARCHAR(80) NOT NULL CONSTRAINT fk_role_template_permission_permission REFERENCES permission (key),
    CONSTRAINT uq_role_template_permission UNIQUE (role_template_id, permission_key));

-- A member is active until removed; a removed member's row is kept so they can be invited again.
-- A role is granted only in the organization that defines it.
CREATE TABLE organization_membership (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_organization_membership PRIMARY KEY,
    organization_id BIGINT NOT NULL CONSTRAINT fk_org_membership_org REFERENCES organization (id),
    user_id BIGINT NOT NULL CONSTRAINT fk_org_membership_user REFERENCES app_user (id),
    role_definition_id BIGINT NOT NULL,
    status VARCHAR(32) NOT NULL CONSTRAINT ck_organization_membership_status CHECK (status IN ('ACTIVE', 'REMOVED')),
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_organization_membership_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_organization_membership_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_org_membership_org_user UNIQUE (organization_id, user_id),
    -- What a reviewer's assignment names: the member while active.
    CONSTRAINT uq_org_membership_org_user_status UNIQUE (organization_id, user_id, status),
    CONSTRAINT fk_org_membership_role_definition FOREIGN KEY (organization_id, role_definition_id)
        REFERENCES role_definition (organization_id, id));

CREATE INDEX idx_org_membership_user ON organization_membership (user_id);
CREATE INDEX idx_app_user_current_organization ON app_user (current_organization_id);
CREATE INDEX idx_role_permission_permission ON role_permission (permission_key);
CREATE INDEX idx_role_template_permission_permission ON role_template_permission (permission_key);
CREATE INDEX idx_org_membership_role ON organization_membership (organization_id, role_definition_id);

-- Invitees answer from Notifications, signed in with the invited address. An invitation is expired
-- once its time has passed, which is not stored; one waits per address in an organization at a time.
CREATE TABLE invitation (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_invitation PRIMARY KEY,
    organization_id BIGINT NOT NULL CONSTRAINT fk_invitation_org REFERENCES organization (id),
    role_definition_id BIGINT NOT NULL,
    email VARCHAR(200) NOT NULL,
    status VARCHAR(32) NOT NULL CONSTRAINT ck_invitation_status CHECK (status IN ('PENDING', 'ACCEPTED', 'REVOKED', 'DECLINED')),
    expires_at TIMESTAMPTZ NOT NULL,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_invitation_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_invitation_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT fk_invitation_role_definition FOREIGN KEY (organization_id, role_definition_id)
        REFERENCES role_definition (organization_id, id));

CREATE UNIQUE INDEX uq_invitation_pending_email ON invitation (organization_id, lower(email)) WHERE status = 'PENDING';
-- Signing in or up finds the invitations waiting for an address across organizations.
CREATE INDEX idx_invitation_pending_address ON invitation (lower(email)) WHERE status = 'PENDING';
CREATE INDEX idx_invitation_organization ON invitation (organization_id, role_definition_id);
CREATE INDEX idx_invitation_created_by ON invitation (created_by_principal_id);

-- ================================================================================================
-- Models
-- ================================================================================================

-- Models, the environments they run in, and plugins.

-- An environment: the Python and the distributions a bundle's lock names, plus the mlbundle release
-- that wrote it, which the runtime's builder installs once and every model needing the same files
-- shares. A row describes one environment for good, so a stored result still says what computed it
-- after the environment's files are removed. Models, results and the runtime name it by its key.
CREATE TABLE runtime_environment (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_runtime_environment PRIMARY KEY,
    environment_key VARCHAR(64) NOT NULL CONSTRAINT uq_runtime_environment_key UNIQUE,
    -- mlbundle's digest of the lock (Python, packages and wheel digests).
    lock_digest VARCHAR(64) NOT NULL,
    writer_version VARCHAR(64) NOT NULL,
    python_version VARCHAR(32) NOT NULL,
    packages JSONB NOT NULL,
    -- The bundle's canonical pylock.toml, which the builder installs.
    lock_toml TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL);

-- A model's row is written once its artifact is in object storage, the artifact's only home, and
-- verified: the row names the exact object version and the artifact's SHA-256. The artifact a row
-- names is fixed for good, so a result that names the model names the exact artifact that computed
-- it; the environment can be prepared again, so a result keeps the one that computed it.
-- lock_version is the row's optimistic lock, not a version of the model.
CREATE TABLE model (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_model PRIMARY KEY,
    lock_version BIGINT NOT NULL DEFAULT 0,
    organization_id BIGINT NOT NULL CONSTRAINT fk_model_organization REFERENCES organization (id),
    name VARCHAR(100) NOT NULL CONSTRAINT ck_model_name_present CHECK (btrim(name) <> ''),
    type VARCHAR(255) NOT NULL,
    specific_type VARCHAR(255) NOT NULL,
    file_name VARCHAR(255) NOT NULL,
    storage_bucket VARCHAR(100) NOT NULL,
    storage_object_key VARCHAR(512) NOT NULL,
    storage_version_id VARCHAR(255) NOT NULL,
    storage_etag VARCHAR(128) NOT NULL,
    -- One stored object is one model's: deleting it can never take another's artifact.
    CONSTRAINT uq_model_storage_object UNIQUE (storage_bucket, storage_object_key, storage_version_id),
    size_bytes BIGINT NOT NULL CONSTRAINT ck_model_size CHECK (size_bytes > 0),
    artifact_sha256 VARCHAR(64) NOT NULL CONSTRAINT ck_model_artifact_sha256 CHECK (artifact_sha256 ~ '^[0-9a-f]{64}$'),
    artifact_verified_at TIMESTAMPTZ NOT NULL,
    -- What the model's bundle says about it: its manifest as uploaded, and the feature importances
    -- the runtime reads from its structure (absent for models without one).
    input_schema JSONB NOT NULL,
    bundle_manifest JSONB NOT NULL,
    feature_importances JSONB,
    environment_key VARCHAR(64) NOT NULL CONSTRAINT fk_model_environment REFERENCES runtime_environment (environment_key),
    archived_at TIMESTAMPTZ,
    -- Set under the model's lock when a purge of it is asked for, and never cleared.
    purging_at TIMESTAMPTZ,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_model_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_model_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_model_org_id UNIQUE (organization_id, id));

-- A name is one model's in its organization, whatever its case.
CREATE UNIQUE INDEX uq_model_name_org ON model (organization_id, lower(name));
CREATE INDEX idx_search_model_name_trgm ON model USING GIN (lower(name) gin_trgm_ops);
CREATE INDEX idx_search_model_file_trgm ON model USING GIN (lower(file_name) gin_trgm_ops);

-- A model's artifact is written once; what is learned about it later (its runtime state) may change.
CREATE TRIGGER trg_model_artifact_fixed BEFORE UPDATE OF file_name, storage_bucket, storage_object_key,
    storage_version_id, storage_etag, size_bytes, artifact_sha256 ON model FOR EACH ROW
    WHEN ((OLD.file_name, OLD.storage_bucket, OLD.storage_object_key, OLD.storage_version_id, OLD.storage_etag,
        OLD.size_bytes, OLD.artifact_sha256)
        IS DISTINCT FROM (NEW.file_name, NEW.storage_bucket, NEW.storage_object_key, NEW.storage_version_id,
        NEW.storage_etag, NEW.size_bytes, NEW.artifact_sha256))
    EXECUTE FUNCTION refuse_change('ck_model_artifact_fixed');

-- Getting a model ready to run, written with the model: its environment is built and the model
-- loaded there (READY); until then it is PREPARING, claimed by one API instance at a time under a
-- lease, or FAILED with the reason. After an attempt that failed in a way worth retrying it waits,
-- unclaimed, until next_attempt_at.
CREATE TABLE model_preparation (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_model_preparation PRIMARY KEY,
    model_id BIGINT NOT NULL CONSTRAINT uq_model_preparation_model UNIQUE
        CONSTRAINT fk_model_preparation_model REFERENCES model (id) ON DELETE CASCADE,
    state VARCHAR(16) NOT NULL CONSTRAINT ck_model_preparation_state CHECK (state IN ('PREPARING', 'READY', 'FAILED')),
    error_message TEXT,
    attempts INTEGER NOT NULL DEFAULT 0 CONSTRAINT ck_model_preparation_attempts CHECK (attempts >= 0),
    lease_owner VARCHAR(128),
    lease_expires_at TIMESTAMPTZ,
    next_attempt_at TIMESTAMPTZ,
    CONSTRAINT ck_model_preparation_lease CHECK ((lease_owner IS NULL) = (lease_expires_at IS NULL)
        AND (state = 'PREPARING' OR (lease_owner IS NULL AND next_attempt_at IS NULL))),
    CONSTRAINT ck_model_preparation_failed CHECK ((state = 'FAILED') = (error_message IS NOT NULL) OR state = 'PREPARING'));

CREATE INDEX idx_model_preparation_preparing ON model_preparation (model_id) WHERE state = 'PREPARING';

-- A plugin is stored as an object with its metadata row, in one transaction. public_id is the
-- random id its object is stored under, and how the API names the plugin.
CREATE TABLE plugin_metadata (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_plugin_metadata PRIMARY KEY,
    public_id VARCHAR(64) NOT NULL CONSTRAINT uq_plugin_metadata_public_id UNIQUE,
    organization_id BIGINT NOT NULL CONSTRAINT fk_plugin_metadata_org REFERENCES organization (id),
    plugin_type VARCHAR(32) NOT NULL CONSTRAINT ck_plugin_metadata_type CHECK (plugin_type IN ('field', 'report')),
    kind VARCHAR(180),
    file_name VARCHAR(255) NOT NULL,
    content_type VARCHAR(120) NOT NULL,
    storage_bucket VARCHAR(100) NOT NULL,
    storage_object_key VARCHAR(512) NOT NULL,
    storage_version_id VARCHAR(255) NOT NULL,
    size_bytes BIGINT NOT NULL CONSTRAINT ck_plugin_metadata_size CHECK (size_bytes > 0),
    artifact_sha256 VARCHAR(64) NOT NULL CONSTRAINT ck_plugin_metadata_sha256 CHECK (artifact_sha256 ~ '^[0-9a-f]{64}$'),
    CONSTRAINT uq_plugin_metadata_storage_object UNIQUE (storage_bucket, storage_object_key, storage_version_id),
    CONSTRAINT uq_plugin_metadata_org_id UNIQUE (organization_id, id),
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_plugin_metadata_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_plugin_metadata_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL);

-- A plugin's identity, kind and stored key are fixed; anonymizing its author's name writes a new
-- version of the same object (version, size and digest change, the code does not).
CREATE TRIGGER trg_plugin_metadata_fixed BEFORE UPDATE OF public_id, organization_id, plugin_type, kind, storage_object_key
    ON plugin_metadata FOR EACH ROW
    WHEN ((OLD.public_id, OLD.organization_id, OLD.plugin_type, OLD.kind, OLD.storage_object_key)
        IS DISTINCT FROM (NEW.public_id, NEW.organization_id, NEW.plugin_type, NEW.kind, NEW.storage_object_key))
    EXECUTE FUNCTION refuse_change('ck_plugin_metadata_fixed');

CREATE INDEX idx_plugin_catalog ON plugin_metadata (organization_id, updated_at DESC, id);
CREATE INDEX idx_search_plugin_file_trgm ON plugin_metadata USING GIN (lower(file_name) gin_trgm_ops);
CREATE INDEX idx_search_plugin_kind_trgm ON plugin_metadata USING GIN (lower(kind) gin_trgm_ops);

CREATE TRIGGER trg_model_not_purging BEFORE INSERT ON model FOR EACH ROW
    EXECUTE FUNCTION refuse_under_purge('organization', 'organization_id');
CREATE TRIGGER trg_plugin_metadata_not_purging BEFORE INSERT ON plugin_metadata FOR EACH ROW
    EXECUTE FUNCTION refuse_under_purge('organization', 'organization_id');

-- ================================================================================================
-- Schemas
-- ================================================================================================

-- Schemas: versioned form and output contracts, the models each version binds, the drafts being
-- edited, and the bookmarks that pin a version.

CREATE TABLE schema (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_schema PRIMARY KEY,
    organization_id BIGINT NOT NULL CONSTRAINT fk_schema_org REFERENCES organization (id),
    name VARCHAR(180) NOT NULL CONSTRAINT ck_schema_name_present CHECK (btrim(name) <> ''),
    description VARCHAR(800),
    archived_at TIMESTAMPTZ,
    -- Set under the schema's lock when a purge of it is asked for, and never cleared.
    purging_at TIMESTAMPTZ,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_schema_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_schema_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_schema_org_id UNIQUE (organization_id, id));

CREATE UNIQUE INDEX uq_schema_org_name ON schema (organization_id, lower(name));
CREATE INDEX idx_search_schema_name_trgm ON schema USING GIN (lower(name) gin_trgm_ops);

-- A snapshot of a schema, written once with its bindings. It carries its schema's organization.
CREATE TABLE schema_version (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_schema_version PRIMARY KEY,
    organization_id BIGINT NOT NULL,
    schema_id BIGINT NOT NULL,
    version_number INTEGER NOT NULL CONSTRAINT ck_schema_version_number CHECK (version_number >= 1),
    name VARCHAR(180),
    form_schema JSONB NOT NULL,
    -- The document's identity, as artifact_sha256 is a model's: what a run was computed against.
    -- (the bytes of its text, backslashes kept as written: a plain bytea cast would read them as escapes)
    form_schema_sha256 VARCHAR(64) NOT NULL
        GENERATED ALWAYS AS (encode(sha256(decode(replace(form_schema::text, '\', '\\'), 'escape')), 'hex')) STORED,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_schema_version_created_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    -- The transaction that wrote it (top-level, also inside a savepoint): its bindings are written there.
    created_xact XID8 NOT NULL DEFAULT pg_current_xact_id(),
    CONSTRAINT uq_schema_version_schema_version UNIQUE (schema_id, version_number),
    CONSTRAINT uq_schema_version_schema_id UNIQUE (schema_id, id),
    CONSTRAINT uq_schema_version_org_id UNIQUE (organization_id, id),
    CONSTRAINT fk_schema_version_schema FOREIGN KEY (organization_id, schema_id)
        REFERENCES schema (organization_id, id));

CREATE UNIQUE INDEX uq_schema_version_schema_name ON schema_version (schema_id, lower(name)) WHERE name IS NOT NULL;

-- A snapshot is written once: what it belongs to, its number and its document never change.
CREATE TRIGGER trg_schema_version_fixed BEFORE UPDATE OF organization_id, schema_id, version_number, form_schema,
    created_xact ON schema_version FOR EACH ROW
    WHEN ((OLD.organization_id, OLD.schema_id, OLD.version_number, OLD.form_schema, OLD.created_xact)
        IS DISTINCT FROM (NEW.organization_id, NEW.schema_id, NEW.version_number, NEW.form_schema, NEW.created_xact))
    EXECUTE FUNCTION refuse_change('ck_schema_version_fixed');

-- A snapshot binds only models of its own organization.
CREATE TABLE schema_model_binding (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_schema_model_binding PRIMARY KEY,
    organization_id BIGINT NOT NULL,
    schema_version_id BIGINT NOT NULL,
    model_id BIGINT NOT NULL,
    plugin_policy JSONB NOT NULL,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_schema_binding_created_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_schema_binding_model UNIQUE (schema_version_id, model_id),
    CONSTRAINT fk_schema_binding_version FOREIGN KEY (organization_id, schema_version_id)
        REFERENCES schema_version (organization_id, id),
    CONSTRAINT fk_schema_binding_model FOREIGN KEY (organization_id, model_id) REFERENCES model (organization_id, id));

CREATE INDEX idx_schema_binding_model ON schema_model_binding (organization_id, model_id);

-- A snapshot's parts (the models it binds, the plugins it renders with) are written in the
-- transaction that writes the snapshot and never change: whatever pins the snapshot (a run, a
-- bookmark, a job, a review) keeps them. They are removed only while the snapshot has no runs: with
-- an unused schema, or by a purge, which removes runs first. The trigger names the constraint.
CREATE FUNCTION snapshot_part_is_fixed() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'UPDATE'
        OR (TG_OP = 'INSERT' AND NOT EXISTS (SELECT 1 FROM schema_version
            WHERE id = NEW.schema_version_id AND created_xact = pg_current_xact_id()))
        OR (TG_OP = 'DELETE' AND EXISTS (SELECT 1 FROM prediction_run WHERE schema_version_id = OLD.schema_version_id)) THEN
        RAISE EXCEPTION 'A snapshot''s % cannot change once it is written: violates check constraint "%"',
            TG_TABLE_NAME, TG_ARGV[0] USING ERRCODE = 'check_violation',
            CONSTRAINT = TG_ARGV[0], TABLE = TG_TABLE_NAME;
    END IF;
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
END $$;
CREATE TRIGGER trg_schema_model_binding_fixed BEFORE INSERT OR UPDATE OR DELETE ON schema_model_binding
    FOR EACH ROW EXECUTE FUNCTION snapshot_part_is_fixed('ck_schema_binding_fixed');

-- A snapshot binds at least one model by the end of the transaction that writes it.
CREATE FUNCTION schema_version_binds_a_model() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM schema_version WHERE id = NEW.id)
        AND NOT EXISTS (SELECT 1 FROM schema_model_binding WHERE schema_version_id = NEW.id) THEN
        RAISE EXCEPTION 'A snapshot binds at least one model: violates check constraint "ck_schema_version_bound"' USING ERRCODE = 'check_violation',
            CONSTRAINT = 'ck_schema_version_bound', TABLE = 'schema_version';
    END IF;
    RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER trg_schema_version_bound AFTER INSERT ON schema_version
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION schema_version_binds_a_model();

-- The plugin that draws each custom kind a snapshot's form names, fixed when the snapshot is
-- published, so the snapshot renders as it was published whatever the organization's library holds
-- later. A plugin a snapshot uses cannot be deleted. Written with the snapshot, like its bindings.
CREATE TABLE schema_version_plugin (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_schema_version_plugin PRIMARY KEY,
    organization_id BIGINT NOT NULL,
    schema_version_id BIGINT NOT NULL,
    plugin_metadata_id BIGINT NOT NULL,
    CONSTRAINT uq_schema_version_plugin UNIQUE (schema_version_id, plugin_metadata_id),
    CONSTRAINT fk_schema_version_plugin_version FOREIGN KEY (organization_id, schema_version_id)
        REFERENCES schema_version (organization_id, id) ON DELETE CASCADE,
    CONSTRAINT fk_schema_version_plugin_plugin FOREIGN KEY (organization_id, plugin_metadata_id)
        REFERENCES plugin_metadata (organization_id, id));

CREATE INDEX idx_schema_version_plugin_plugin ON schema_version_plugin (organization_id, plugin_metadata_id);
CREATE TRIGGER trg_schema_version_plugin_fixed BEFORE INSERT OR UPDATE OR DELETE ON schema_version_plugin
    FOR EACH ROW EXECUTE FUNCTION snapshot_part_is_fixed('ck_schema_version_plugin_fixed');


-- A draft stays on snapshots of its own schema; publishing records the snapshot it became, which
-- no other draft became. A draft
-- is a document still being written: its bindings are checked against the organization's models
-- when it is published as a snapshot, whose bindings are rows. A snapshot's bindings never change,
-- so what the draft started from is its base snapshot's.
CREATE TABLE schema_draft (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_schema_draft PRIMARY KEY,
    schema_id BIGINT NOT NULL CONSTRAINT fk_schema_draft_schema REFERENCES schema (id),
    base_version_id BIGINT NOT NULL,
    published_version_id BIGINT,
    name VARCHAR(180) NOT NULL CONSTRAINT ck_schema_draft_name_present CHECK (btrim(name) <> ''),
    status VARCHAR(32) NOT NULL CONSTRAINT ck_schema_draft_status CHECK (status IN ('DRAFT', 'CONFLICT', 'PUBLISHED')),
    lock_version BIGINT NOT NULL DEFAULT 0,
    form_schema JSONB NOT NULL,
    bindings JSONB NOT NULL,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_schema_draft_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_schema_draft_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT fk_schema_draft_base FOREIGN KEY (schema_id, base_version_id) REFERENCES schema_version (schema_id, id),
    CONSTRAINT fk_schema_draft_published FOREIGN KEY (schema_id, published_version_id)
        REFERENCES schema_version (schema_id, id),
    CONSTRAINT uq_schema_draft_published UNIQUE (published_version_id),
    CONSTRAINT ck_schema_draft_published_version CHECK ((status = 'PUBLISHED') = (published_version_id IS NOT NULL)));

CREATE INDEX idx_schema_draft_base ON schema_draft (schema_id, base_version_id);

-- A bookmark describes itself: in its schema's repository and on its public page. It is private
-- until a member publishes it; public_id is assigned on the first publish or when an API client is
-- given the bookmark, and kept afterwards, so a shared /explore link survives unpublishing. A
-- published bookmark may carry a note for its visitors: a paper, a DOI, terms of use.
CREATE TABLE schema_bookmark (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_schema_bookmark PRIMARY KEY,
    schema_id BIGINT NOT NULL CONSTRAINT fk_schema_bookmark_schema REFERENCES schema (id),
    schema_version_id BIGINT NOT NULL,
    name VARCHAR(180) NOT NULL CONSTRAINT ck_schema_bookmark_name_present CHECK (btrim(name) <> ''),
    description VARCHAR(800),
    visibility VARCHAR(16) NOT NULL DEFAULT 'PRIVATE'
        CONSTRAINT ck_schema_bookmark_visibility CHECK (visibility IN ('PRIVATE', 'PUBLIC')),
    public_id VARCHAR(36) CONSTRAINT uq_schema_bookmark_public_id UNIQUE,
    publication_note VARCHAR(1000),
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_schema_bookmark_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_schema_bookmark_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_schema_bookmark_schema_id UNIQUE (schema_id, id),
    CONSTRAINT uq_schema_bookmark_id_visibility UNIQUE (id, visibility),
    CONSTRAINT fk_schema_bookmark_version FOREIGN KEY (schema_id, schema_version_id) REFERENCES schema_version (schema_id, id),
    CONSTRAINT ck_schema_bookmark_public_has_id CHECK (visibility = 'PRIVATE' OR public_id IS NOT NULL));

CREATE UNIQUE INDEX uq_schema_bookmark_schema_name ON schema_bookmark (schema_id, lower(name));
CREATE INDEX idx_schema_bookmark_version ON schema_bookmark (schema_version_id);

-- The bookmarks a person keeps at the top of their profile, at most six, in the order of their
-- slots. A bookmark is pinned once, by the owner of its personal account, and only while it is
-- public: unpublishing it takes its pins down in the same transaction (the key is checked at commit).
-- The slot is unique only at commit, so a reorder can swap two pins in place.
CREATE TABLE profile_pin (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_profile_pin PRIMARY KEY,
    schema_bookmark_id BIGINT NOT NULL,
    bookmark_visibility VARCHAR(16) NOT NULL GENERATED ALWAYS AS ('PUBLIC') STORED,
    user_id BIGINT NOT NULL CONSTRAINT fk_profile_pin_user REFERENCES app_user (id) ON DELETE CASCADE,
    slot INTEGER NOT NULL CONSTRAINT ck_profile_pin_slot CHECK (slot BETWEEN 0 AND 5),
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_profile_pin_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_profile_pin_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_profile_pin_bookmark UNIQUE (user_id, schema_bookmark_id),
    CONSTRAINT fk_profile_pin_bookmark FOREIGN KEY (schema_bookmark_id, bookmark_visibility)
        REFERENCES schema_bookmark (id, visibility) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT uq_profile_pin_slot UNIQUE (user_id, slot) DEFERRABLE INITIALLY DEFERRED);

CREATE INDEX idx_profile_pin_bookmark ON profile_pin (schema_bookmark_id, bookmark_visibility);

CREATE TRIGGER trg_schema_not_purging BEFORE INSERT ON schema FOR EACH ROW
    EXECUTE FUNCTION refuse_under_purge('organization', 'organization_id');
CREATE TRIGGER trg_schema_version_not_purging BEFORE INSERT ON schema_version FOR EACH ROW
    EXECUTE FUNCTION refuse_under_purge('schema', 'schema_id');
CREATE TRIGGER trg_schema_model_binding_not_purging BEFORE INSERT ON schema_model_binding FOR EACH ROW
    EXECUTE FUNCTION refuse_under_purge('model', 'model_id');
CREATE TRIGGER trg_schema_draft_not_purging BEFORE INSERT ON schema_draft FOR EACH ROW
    EXECUTE FUNCTION refuse_under_purge('schema', 'schema_id');
CREATE TRIGGER trg_schema_bookmark_not_purging BEFORE INSERT ON schema_bookmark FOR EACH ROW
    EXECUTE FUNCTION refuse_under_purge('schema', 'schema_id');

-- ================================================================================================
-- Predictions
-- ================================================================================================

-- Predictions: runs, their results, the public examples of a bookmark, the inference table's
-- projection, and bulk jobs.

-- origin says where a run was made: the workspace form, a bookmark's public page, or an API
-- client. Its author is the member, the visitor or the client who made it. A run carries its
-- snapshot's schema, so the bookmark it was reached through is one of that schema; the bookmark is
-- only how it was reached, so a run outlives it. A run is written once and never changed.
CREATE TABLE prediction_run (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_prediction_run PRIMARY KEY,
    organization_id BIGINT NOT NULL,
    schema_id BIGINT NOT NULL,
    schema_version_id BIGINT NOT NULL,
    schema_bookmark_id BIGINT,
    name VARCHAR(255) NOT NULL CONSTRAINT ck_prediction_run_name_present CHECK (btrim(name) <> ''),
    input_data JSONB NOT NULL,
    status VARCHAR(32) NOT NULL CONSTRAINT ck_prediction_run_status CHECK (status IN ('SUCCESS', 'PARTIAL_SUCCESS', 'FAILED')),
    origin VARCHAR(16) NOT NULL CONSTRAINT ck_prediction_run_origin CHECK (origin IN ('WORKSPACE', 'PUBLIC', 'API')),
    created_by_principal_id BIGINT NOT NULL,
    -- The author's kind, which the origin agrees with: an API run is a client's and only a client's,
    -- and a visitor runs only on a public page.
    created_by_kind VARCHAR(16) NOT NULL,
    -- The client an API run was made with, while it exists (its key is added under API access): of the run's organization.
    api_client_id BIGINT CONSTRAINT ck_prediction_run_api_client CHECK (api_client_id IS NULL OR origin = 'API'),
    created_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT fk_prediction_run_created_by FOREIGN KEY (created_by_principal_id, created_by_kind)
        REFERENCES principal (id, kind),
    CONSTRAINT ck_prediction_run_origin_author CHECK ((origin = 'API') = (created_by_kind = 'API_CLIENT')
        AND (created_by_kind <> 'VISITOR' OR origin = 'PUBLIC')),
    CONSTRAINT uq_prediction_run_schema_id UNIQUE (schema_id, id),
    CONSTRAINT uq_prediction_run_version_id UNIQUE (schema_version_id, id),
    CONSTRAINT fk_prediction_run_schema FOREIGN KEY (organization_id, schema_id) REFERENCES schema (organization_id, id),
    CONSTRAINT fk_prediction_run_version FOREIGN KEY (schema_id, schema_version_id) REFERENCES schema_version (schema_id, id),
    CONSTRAINT fk_prediction_run_bookmark FOREIGN KEY (schema_id, schema_bookmark_id)
        REFERENCES schema_bookmark (schema_id, id) ON DELETE SET NULL (schema_bookmark_id));

-- A run's name is unique on its snapshot, whatever its case.
CREATE UNIQUE INDEX uq_prediction_run_version_name ON prediction_run (schema_version_id, lower(name));

-- A run is a record: once written only the bookmark it came from may go (with the bookmark).
CREATE TRIGGER trg_prediction_run_fixed BEFORE UPDATE OF id, organization_id, schema_id, schema_version_id, name, input_data, status,
    origin, created_by_principal_id, created_by_kind, created_at ON prediction_run FOR EACH ROW
    WHEN ((OLD.id, OLD.organization_id, OLD.schema_id, OLD.schema_version_id, OLD.name, OLD.input_data, OLD.status, OLD.origin,
        OLD.created_by_principal_id, OLD.created_by_kind, OLD.created_at)
        IS DISTINCT FROM (NEW.id, NEW.organization_id, NEW.schema_id, NEW.schema_version_id, NEW.name, NEW.input_data, NEW.status, NEW.origin,
        NEW.created_by_principal_id, NEW.created_by_kind, NEW.created_at))
    EXECUTE FUNCTION refuse_change('ck_prediction_run_fixed');

-- The inference catalog filters runs by bookmark and pages them by creation time, newest first and
-- then by id; a public page reads back its author's runs of its bookmark.
CREATE INDEX idx_prediction_run_bookmark ON prediction_run (schema_bookmark_id);
CREATE INDEX idx_prediction_run_created ON prediction_run (organization_id, created_at DESC, id);
CREATE INDEX idx_prediction_run_schema_created ON prediction_run (schema_id, created_at DESC);
CREATE INDEX idx_prediction_run_author_bookmark ON prediction_run (created_by_principal_id, schema_bookmark_id);
CREATE INDEX idx_search_run_name_trgm ON prediction_run USING GIN (lower(name) gin_trgm_ops);

-- A result carries its run's snapshot, so its model is one that snapshot binds. environment_key is
-- the environment that computed it.
CREATE TABLE prediction_result (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_prediction_result PRIMARY KEY,
    schema_version_id BIGINT NOT NULL,
    prediction_run_id BIGINT NOT NULL,
    model_id BIGINT NOT NULL,
    environment_key VARCHAR(64) NOT NULL CONSTRAINT fk_prediction_result_environment
        REFERENCES runtime_environment (environment_key),
    status VARCHAR(32) NOT NULL CONSTRAINT ck_prediction_result_status CHECK (status IN ('SUCCESS', 'FAILED')),
    error_message TEXT,
    error_detail JSONB,
    -- A failed result says why, as text and as the runtime's answer; a successful one does not.
    CONSTRAINT ck_prediction_result_failed CHECK ((status = 'FAILED') = (error_message IS NOT NULL)),
    CONSTRAINT ck_prediction_result_error CHECK ((error_message IS NULL) = (error_detail IS NULL)),
    model_input JSONB NOT NULL,
    -- What the model answered; a failed result answered nothing but its error.
    output JSONB,
    CONSTRAINT ck_prediction_result_output CHECK ((status = 'SUCCESS') = (output IS NOT NULL)),
    -- The seal a workspace result was saved from: one execution is saved in one run.
    attestation_sha256 VARCHAR(64) CONSTRAINT uq_prediction_result_attestation UNIQUE
        CONSTRAINT ck_prediction_result_attestation CHECK (attestation_sha256 ~ '^[0-9a-f]{64}$'),
    created_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_prediction_result_run_model UNIQUE (prediction_run_id, model_id),
    CONSTRAINT uq_prediction_result_run_id UNIQUE (prediction_run_id, id),
    CONSTRAINT fk_prediction_result_run FOREIGN KEY (schema_version_id, prediction_run_id)
        REFERENCES prediction_run (schema_version_id, id),
    CONSTRAINT fk_prediction_result_binding FOREIGN KEY (schema_version_id, model_id)
        REFERENCES schema_model_binding (schema_version_id, model_id));

CREATE INDEX idx_prediction_result_model ON prediction_result (model_id);
CREATE INDEX idx_prediction_result_binding ON prediction_result (schema_version_id, model_id);

-- At commit a run has one result for every model its snapshot binds, and its status says how they
-- went: all succeeded, all failed, or some of each. Checked whenever a run or a result is written.
CREATE FUNCTION prediction_run_agrees_with_results() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    run_id BIGINT;
    run_status VARCHAR(32);
    version_id BIGINT;
    results INTEGER;
    succeeded INTEGER;
BEGIN
    IF TG_TABLE_NAME = 'prediction_run' THEN
        run_id := NEW.id;
    ELSE
        run_id := NEW.prediction_run_id;
    END IF;
    SELECT status, schema_version_id INTO run_status, version_id FROM prediction_run WHERE id = run_id;
    IF NOT FOUND THEN
        RETURN NULL; -- removed again in the same transaction
    END IF;
    SELECT count(*), count(*) FILTER (WHERE status = 'SUCCESS') INTO results, succeeded
        FROM prediction_result WHERE prediction_run_id = run_id;
    IF results <> (SELECT count(*) FROM schema_model_binding WHERE schema_version_id = version_id)
        OR run_status <> (CASE WHEN succeeded = results THEN 'SUCCESS' WHEN succeeded = 0 THEN 'FAILED'
            ELSE 'PARTIAL_SUCCESS' END) THEN
        RAISE EXCEPTION 'Run % does not agree with its results: violates check constraint "ck_prediction_run_results"', run_id USING ERRCODE = 'check_violation',
            CONSTRAINT = 'ck_prediction_run_results', TABLE = 'prediction_run';
    END IF;
    RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER trg_prediction_run_results AFTER INSERT ON prediction_run
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION prediction_run_agrees_with_results();
CREATE CONSTRAINT TRIGGER trg_prediction_result_run AFTER INSERT ON prediction_result
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION prediction_run_agrees_with_results();

-- A result goes only with its run (by the commit, the run is gone too), or with a snapshot a purge
-- is destroying, whose runs go in a later step of the same purge.
CREATE FUNCTION prediction_result_goes_with_its_run() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM prediction_run WHERE id = OLD.prediction_run_id)
        AND NOT EXISTS (SELECT 1 FROM purge_job_version WHERE schema_version_id = OLD.schema_version_id) THEN
        RAISE EXCEPTION 'A result is removed only with its run: violates check constraint "ck_prediction_result_with_run"' USING ERRCODE = 'check_violation',
            CONSTRAINT = 'ck_prediction_result_with_run', TABLE = 'prediction_result';
    END IF;
    RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER trg_prediction_result_with_run AFTER DELETE ON prediction_result
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION prediction_result_goes_with_its_run();

-- A result is what a model computed: it never changes.
CREATE TRIGGER trg_prediction_result_fixed BEFORE UPDATE ON prediction_result FOR EACH ROW
    WHEN (OLD IS DISTINCT FROM NEW) EXECUTE FUNCTION refuse_change('ck_prediction_result_fixed');

-- A run a member explicitly marked as a public example of a bookmark of its schema. The run stays
-- the source of truth for the inputs: nothing is copied here. An example is served only while the
-- bookmark is public and still pins the snapshot the run executed on, so a moved bookmark needs no
-- cleanup. Rows leave with their run or their bookmark.
CREATE TABLE schema_bookmark_example (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_schema_bookmark_example PRIMARY KEY,
    schema_id BIGINT NOT NULL,
    schema_bookmark_id BIGINT NOT NULL,
    prediction_run_id BIGINT NOT NULL,
    public_id VARCHAR(36) NOT NULL CONSTRAINT uq_schema_bookmark_example_public_id UNIQUE,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_schema_bookmark_example_created_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_schema_bookmark_example_bookmark_run UNIQUE (schema_bookmark_id, prediction_run_id),
    CONSTRAINT fk_schema_bookmark_example_bookmark FOREIGN KEY (schema_id, schema_bookmark_id)
        REFERENCES schema_bookmark (schema_id, id) ON DELETE CASCADE,
    CONSTRAINT fk_schema_bookmark_example_run FOREIGN KEY (schema_id, prediction_run_id)
        REFERENCES prediction_run (schema_id, id) ON DELETE CASCADE);

CREATE INDEX idx_schema_bookmark_example_run ON schema_bookmark_example (prediction_run_id);

-- A rebuildable cache, not a source of truth: the inferences table's columns and sorts are derived
-- from stored runs (inputs, reports, answers), and emptying this table loses nothing.
-- What a run shows does not depend on the locale, only how it is written and compared does, so
-- each run's projection is kept once, by a background refresh, and every locale formats and
-- collates it when it reads it. One row per run: the raw value of each of its data columns, its
-- feedback status, and a digest of its snapshot and of its columns' ids and groups (runs sharing
-- one have the same columns), as projection_version projects them with its snapshot's models named
-- as models_stamp says. The row holds nothing it is not the only home of: the run's snapshot is
-- read from the run. A trigger on the answers adds one to answer_changes in the transaction that
-- changes them (a row may exist for that alone, before it is projected); the projection is current while
-- projected_changes still equals it. A migration that changes answers or what a row is projected
-- from must empty this table.
CREATE TABLE prediction_run_projection (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_prediction_run_projection PRIMARY KEY,
    prediction_run_id BIGINT NOT NULL CONSTRAINT uq_prediction_run_projection_run UNIQUE
        CONSTRAINT fk_prediction_run_projection_run REFERENCES prediction_run (id) ON DELETE CASCADE,
    answer_changes BIGINT NOT NULL DEFAULT 0,
    projected_changes BIGINT,
    projection_version INTEGER,
    models_stamp TEXT,
    layout_sha256 VARCHAR(64) CONSTRAINT ck_prediction_run_projection_layout CHECK (layout_sha256 ~ '^[0-9a-f]{64}$'),
    feedback_status VARCHAR(32) CONSTRAINT ck_prediction_run_projection_feedback_status
        CHECK (feedback_status IN ('COMPLETED', 'PENDING', 'NOT_REQUIRED', 'ERROR')),
    cell_values JSONB,
    -- A row is either only counting answer changes, or projected in full.
    CONSTRAINT ck_prediction_run_projection_projected CHECK (num_nulls(projected_changes, projection_version, models_stamp, layout_sha256,
        feedback_status, cell_values) IN (0, 6)));

-- A bulk upload runs on the server as a job, so it survives the browser tab that started it. The
-- client uploads its rows once; API workers claim a job with SELECT ... FOR UPDATE SKIP LOCKED and
-- hold it under a lease, so a crashed or restarted worker's job is claimed again once its lease
-- expires. Each row ends as a stored run (DONE) or with the reason it could not (FAILED). A job runs
-- a bookmark on the snapshot it pinned when the job started, so both are of one schema, the job's
-- organization's; the job carries that schema. A job is work in flight: it leaves with its bookmark
-- or its snapshot.
CREATE TABLE prediction_job (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_prediction_job PRIMARY KEY,
    organization_id BIGINT NOT NULL,
    schema_id BIGINT NOT NULL,
    -- The bookmark it runs; a finished job outlives its bookmark, an open one keeps it.
    schema_bookmark_id BIGINT,
    schema_version_id BIGINT NOT NULL,
    status VARCHAR(16) NOT NULL CONSTRAINT ck_prediction_job_status CHECK (status IN ('QUEUED', 'RUNNING', 'COMPLETED', 'CANCELLED')),
    total_rows INTEGER NOT NULL CONSTRAINT ck_prediction_job_total CHECK (total_rows >= 1),
    done_rows INTEGER NOT NULL DEFAULT 0,
    failed_rows INTEGER NOT NULL DEFAULT 0,
    lease_owner VARCHAR(128),
    lease_expires_at TIMESTAMPTZ,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_prediction_job_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_prediction_job_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    finished_at TIMESTAMPTZ,
    -- Why the system stopped it before its rows ran (its pending rows failed with this reason).
    stop_reason TEXT CONSTRAINT ck_prediction_job_stop_reason CHECK (stop_reason IS NULL OR status = 'COMPLETED'),
    -- A running job is leased, and only a running one; a lease has an owner and an expiry together.
    CONSTRAINT ck_prediction_job_lease CHECK ((lease_owner IS NULL) = (lease_expires_at IS NULL)
        AND (status = 'RUNNING') = (lease_owner IS NOT NULL)),
    CONSTRAINT ck_prediction_job_completed CHECK (status <> 'COMPLETED' OR done_rows + failed_rows = total_rows),
    CONSTRAINT ck_prediction_job_finished CHECK ((finished_at IS NOT NULL) = (status IN ('COMPLETED', 'CANCELLED'))),
    CONSTRAINT ck_prediction_job_rows CHECK (done_rows >= 0 AND failed_rows >= 0 AND done_rows + failed_rows <= total_rows),
    CONSTRAINT uq_prediction_job_id_version UNIQUE (id, schema_version_id),
    CONSTRAINT fk_prediction_job_schema FOREIGN KEY (organization_id, schema_id) REFERENCES schema (organization_id, id),
    CONSTRAINT fk_prediction_job_bookmark FOREIGN KEY (schema_id, schema_bookmark_id)
        REFERENCES schema_bookmark (schema_id, id) ON DELETE SET NULL (schema_bookmark_id),
    CONSTRAINT ck_prediction_job_open_bookmark CHECK (status IN ('COMPLETED', 'CANCELLED') OR schema_bookmark_id IS NOT NULL),
    CONSTRAINT fk_prediction_job_version FOREIGN KEY (schema_id, schema_version_id)
        REFERENCES schema_version (schema_id, id) ON DELETE CASCADE);

CREATE INDEX idx_prediction_job_open ON prediction_job (id) WHERE status IN ('QUEUED', 'RUNNING');
CREATE INDEX idx_prediction_job_bookmark ON prediction_job (schema_bookmark_id, id DESC);
CREATE INDEX idx_prediction_job_version ON prediction_job (schema_version_id);
CREATE INDEX idx_prediction_job_created_by ON prediction_job (created_by_principal_id);
CREATE INDEX idx_prediction_job_organization ON prediction_job (organization_id, schema_id);

-- A row's run is one of its job's snapshot: the row carries the job's snapshot.
CREATE TABLE prediction_job_row (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_prediction_job_row PRIMARY KEY,
    prediction_job_id BIGINT NOT NULL,
    schema_version_id BIGINT NOT NULL,
    row_index INTEGER NOT NULL CONSTRAINT ck_prediction_job_row_index CHECK (row_index >= 0),
    name VARCHAR(255) NOT NULL CONSTRAINT ck_prediction_job_row_name_present CHECK (btrim(name) <> ''),
    -- What the row sends, kept until it is a run: a done row's inputs are its run's.
    input_data JSONB,
    model_inputs JSONB,
    status VARCHAR(16) NOT NULL CONSTRAINT ck_prediction_job_row_status CHECK (status IN ('PENDING', 'DONE', 'FAILED')),
    prediction_run_id BIGINT,
    error_message TEXT,
    CONSTRAINT uq_prediction_job_row UNIQUE (prediction_job_id, row_index),
    CONSTRAINT fk_prediction_job_row_job FOREIGN KEY (prediction_job_id, schema_version_id)
        REFERENCES prediction_job (id, schema_version_id) ON DELETE CASCADE,
    CONSTRAINT fk_prediction_job_row_run FOREIGN KEY (schema_version_id, prediction_run_id)
        REFERENCES prediction_run (schema_version_id, id) ON DELETE SET NULL (prediction_run_id),
    CONSTRAINT ck_prediction_job_row_error CHECK ((status = 'FAILED') = (error_message IS NOT NULL)),
    CONSTRAINT ck_prediction_job_row_run CHECK (prediction_run_id IS NULL OR status = 'DONE'),
    CONSTRAINT ck_prediction_job_row_payload CHECK ((status = 'DONE') = (input_data IS NULL)
        AND (input_data IS NULL) = (model_inputs IS NULL)));

CREATE INDEX idx_prediction_job_row_pending ON prediction_job_row (prediction_job_id, row_index) WHERE status = 'PENDING';
-- A run is the outcome of at most one row.
CREATE UNIQUE INDEX uq_prediction_job_row_run ON prediction_job_row (prediction_run_id) WHERE prediction_run_id IS NOT NULL;

CREATE TRIGGER trg_prediction_run_not_purging BEFORE INSERT ON prediction_run FOR EACH ROW
    EXECUTE FUNCTION refuse_under_purge('schema', 'schema_id');
CREATE TRIGGER trg_prediction_job_not_purging BEFORE INSERT ON prediction_job FOR EACH ROW
    EXECUTE FUNCTION refuse_under_purge('schema', 'schema_id');

-- ================================================================================================
-- Reviews and feedback
-- ================================================================================================

-- Reviews of a schema version's runs, who answers them, and the answers themselves.

-- A review stays on a snapshot of its own schema in its own organization.
CREATE TABLE schema_review (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_schema_review PRIMARY KEY,
    public_id VARCHAR(36) NOT NULL CONSTRAINT uq_schema_review_public_id UNIQUE,
    organization_id BIGINT NOT NULL CONSTRAINT fk_schema_review_org REFERENCES organization (id),
    schema_id BIGINT NOT NULL,
    schema_version_id BIGINT NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_schema_review_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_schema_review_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_schema_review_id_version UNIQUE (id, schema_version_id),
    CONSTRAINT uq_schema_review_org_id UNIQUE (organization_id, id),
    CONSTRAINT fk_schema_review_schema FOREIGN KEY (organization_id, schema_id) REFERENCES schema (organization_id, id),
    CONSTRAINT fk_schema_review_version FOREIGN KEY (schema_id, schema_version_id) REFERENCES schema_version (schema_id, id));

CREATE INDEX idx_schema_review_schema ON schema_review (organization_id, schema_id);
CREATE INDEX idx_schema_review_version ON schema_review (schema_id, schema_version_id);

-- A reviewer is a member of the review's organization; the row carries the review's organization.
-- A reviewer who is gone has nothing left to do in a review; the answers they gave stay in it.
CREATE TABLE schema_review_assignee (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_schema_review_assignee PRIMARY KEY,
    organization_id BIGINT NOT NULL,
    schema_review_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    -- Names the membership while it is active: removing the member removes the assignment first.
    membership_status VARCHAR(32) NOT NULL GENERATED ALWAYS AS ('ACTIVE') STORED,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_schema_review_assignee_created_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_schema_review_assignee UNIQUE (schema_review_id, user_id),
    CONSTRAINT fk_review_assignee_review FOREIGN KEY (organization_id, schema_review_id)
        REFERENCES schema_review (organization_id, id) ON DELETE CASCADE,
    CONSTRAINT fk_review_assignee_member FOREIGN KEY (organization_id, user_id, membership_status)
        REFERENCES organization_membership (organization_id, user_id, status) ON DELETE CASCADE);

CREATE INDEX idx_schema_review_assignee_member ON schema_review_assignee (organization_id, user_id);
CREATE INDEX idx_schema_review_assignee_user ON schema_review_assignee (user_id);

-- A review covers only runs of the snapshot it reviews: the row carries the review's snapshot.
CREATE TABLE schema_review_run (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_schema_review_run PRIMARY KEY,
    public_id VARCHAR(36) NOT NULL CONSTRAINT uq_schema_review_run_public_id UNIQUE,
    schema_version_id BIGINT NOT NULL,
    schema_review_id BIGINT NOT NULL,
    prediction_run_id BIGINT NOT NULL,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_schema_review_run_created_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_schema_review_run UNIQUE (schema_review_id, prediction_run_id),
    CONSTRAINT uq_schema_review_run_review_id UNIQUE (schema_review_id, id),
    CONSTRAINT fk_schema_review_run_review FOREIGN KEY (schema_review_id, schema_version_id)
        REFERENCES schema_review (id, schema_version_id) ON DELETE CASCADE,
    CONSTRAINT fk_schema_review_run_prediction FOREIGN KEY (schema_version_id, prediction_run_id)
        REFERENCES prediction_run (schema_version_id, id));

CREATE INDEX idx_schema_review_run_prediction ON schema_review_run (schema_version_id, prediction_run_id);

-- A reviewer's submission of their answers on one run of a review: who, and when. Only a reviewer
-- of that review submits; the row carries the review, and leaves with its reviewer.
CREATE TABLE schema_review_run_submission (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_schema_review_run_submission PRIMARY KEY,
    schema_review_id BIGINT NOT NULL,
    schema_review_run_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    submitted_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_schema_review_run_submission UNIQUE (schema_review_run_id, user_id),
    CONSTRAINT fk_schema_review_submission_run FOREIGN KEY (schema_review_id, schema_review_run_id)
        REFERENCES schema_review_run (schema_review_id, id) ON DELETE CASCADE,
    CONSTRAINT fk_schema_review_submission_assignee FOREIGN KEY (schema_review_id, user_id)
        REFERENCES schema_review_assignee (schema_review_id, user_id) ON DELETE CASCADE);

CREATE INDEX idx_schema_review_submission_assignee ON schema_review_run_submission (schema_review_id, user_id);

-- An answer about a result, by its author: a member or a visitor. An answer given in a review
-- belongs to that review, so removing a reviewer's response to one review leaves their answers in
-- other reviews and on the public page as they were; answers given elsewhere (a public page) belong
-- to no review. An author answers each question once per review, and once outside any review; the
-- author outlives their account, so this holds after it is deleted. An answer in a review is about
-- a run the review covers: the row carries its result's run. A review is deleted whole, with its
-- reviewers, runs, submissions, answers and their history; otherwise answers leave only by being
-- deleted, so whatever removes a review's run removes its answers first.
-- question_index is which question of its type it answers.
CREATE TABLE prediction_result_feedback (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_prediction_result_feedback PRIMARY KEY,
    prediction_run_id BIGINT NOT NULL,
    prediction_result_id BIGINT NOT NULL,
    schema_review_id BIGINT,
    feedback_type VARCHAR(32) NOT NULL CONSTRAINT ck_result_feedback_type CHECK (feedback_type IN ('OUTPUT', 'EXPLANATION')),
    question_index INTEGER NOT NULL CONSTRAINT ck_result_feedback_question CHECK (question_index >= 0),
    data_value JSONB NOT NULL,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_result_feedback_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_result_feedback_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    -- An answer is changed only by its author.
    CONSTRAINT ck_result_feedback_own CHECK (updated_by_principal_id = created_by_principal_id),
    CONSTRAINT fk_result_feedback_result FOREIGN KEY (prediction_run_id, prediction_result_id)
        REFERENCES prediction_result (prediction_run_id, id),
    CONSTRAINT fk_result_feedback_review_run FOREIGN KEY (schema_review_id, prediction_run_id)
        REFERENCES schema_review_run (schema_review_id, prediction_run_id),
    CONSTRAINT fk_result_feedback_review FOREIGN KEY (schema_review_id) REFERENCES schema_review (id) ON DELETE CASCADE);

CREATE UNIQUE INDEX uq_result_feedback_author ON prediction_result_feedback
    (prediction_result_id, feedback_type, question_index, created_by_principal_id, schema_review_id) NULLS NOT DISTINCT;
CREATE INDEX idx_result_feedback_run ON prediction_result_feedback (prediction_run_id);
CREATE INDEX idx_result_feedback_review_run ON prediction_result_feedback (schema_review_id, prediction_run_id);
CREATE INDEX idx_result_feedback_created_by ON prediction_result_feedback (created_by_principal_id);

-- An answer given in a review is its reviewer's: its author is assigned to the review when it is
-- written (an assignment may end later; the answer stays).
CREATE FUNCTION result_feedback_by_a_reviewer() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM schema_review_assignee a JOIN principal p ON p.user_id = a.user_id
            WHERE a.schema_review_id = NEW.schema_review_id AND p.id = NEW.created_by_principal_id) THEN
        RAISE EXCEPTION 'Only a reviewer of the review answers in it: violates check constraint "ck_result_feedback_reviewer"' USING ERRCODE = 'check_violation',
            CONSTRAINT = 'ck_result_feedback_reviewer', TABLE = 'prediction_result_feedback';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER trg_result_feedback_reviewer BEFORE INSERT ON prediction_result_feedback FOR EACH ROW
    WHEN (NEW.schema_review_id IS NOT NULL) EXECUTE FUNCTION result_feedback_by_a_reviewer();

-- What an answer is about and whose it is never change; only what it says (and who said it last).
CREATE TRIGGER trg_result_feedback_fixed BEFORE UPDATE ON prediction_result_feedback FOR EACH ROW
    WHEN ((OLD.prediction_run_id, OLD.prediction_result_id, OLD.schema_review_id, OLD.feedback_type, OLD.question_index,
        OLD.created_by_principal_id, OLD.created_at)
        IS DISTINCT FROM (NEW.prediction_run_id, NEW.prediction_result_id, NEW.schema_review_id, NEW.feedback_type,
        NEW.question_index, NEW.created_by_principal_id, NEW.created_at))
    EXECUTE FUNCTION refuse_change('ck_result_feedback_fixed');


-- Every change of an answer, kept when the answer changes again or is removed: whose answer it was,
-- what it said and who changed it. Written by the answers' own trigger, below. An answer removed with its run leaves one DELETED revision, so
-- the removal stays on record once the result is gone: the revision keeps the answer's and the
-- result's ids as plain values, and goes only with its snapshot or its review.
CREATE TABLE prediction_result_feedback_revision (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_prediction_result_feedback_revision PRIMARY KEY,
    feedback_id BIGINT NOT NULL,
    prediction_result_id BIGINT NOT NULL,
    schema_version_id BIGINT NOT NULL CONSTRAINT fk_feedback_revision_version REFERENCES schema_version (id) ON DELETE CASCADE,
    schema_review_id BIGINT,
    author_principal_id BIGINT NOT NULL CONSTRAINT fk_feedback_revision_author REFERENCES principal (id),
    feedback_type VARCHAR(32) NOT NULL CONSTRAINT ck_feedback_revision_type CHECK (feedback_type IN ('OUTPUT', 'EXPLANATION')),
    question_index INTEGER NOT NULL CONSTRAINT ck_feedback_revision_question CHECK (question_index >= 0),
    data_value JSONB,
    change_kind VARCHAR(16) NOT NULL CONSTRAINT ck_feedback_revision_change CHECK (change_kind IN ('CREATED', 'UPDATED', 'DELETED')),
    changed_by_principal_id BIGINT NOT NULL CONSTRAINT fk_feedback_revision_changed_by REFERENCES principal (id),
    changed_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT ck_feedback_revision_value CHECK ((change_kind = 'DELETED') = (data_value IS NULL)),
    -- A review's answers are about its snapshot's runs.
    CONSTRAINT fk_feedback_revision_review FOREIGN KEY (schema_review_id, schema_version_id)
        REFERENCES schema_review (id, schema_version_id) ON DELETE CASCADE);

CREATE INDEX idx_feedback_revision_result ON prediction_result_feedback_revision (prediction_result_id, id);
CREATE INDEX idx_feedback_revision_version ON prediction_result_feedback_revision (schema_version_id);
CREATE INDEX idx_feedback_revision_review ON prediction_result_feedback_revision (schema_review_id, schema_version_id);
CREATE INDEX idx_feedback_revision_feedback ON prediction_result_feedback_revision (feedback_id, id);

-- Every change of an answer, whoever writes it, makes its run's projection stale and is written to
-- the answer's history, in the same transaction. Who changed it is the answer's updated_by for a write; for a removal it is the principal the
-- transaction names in app.principal_id (SET LOCAL), and a removal that names no one is refused.
-- Removing the answers of a snapshot a purge destroys, or of a review being deleted (which takes
-- them with it), records nothing: their history goes with them.
CREATE FUNCTION result_feedback_changed() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    answer prediction_result_feedback%ROWTYPE;
    actor BIGINT;
    version_id BIGINT;
BEGIN
    IF TG_OP = 'DELETE' THEN
        answer := OLD;
        actor := nullif(current_setting('app.principal_id', true), '')::bigint;
    ELSE
        answer := NEW;
        actor := NEW.updated_by_principal_id;
    END IF;
    INSERT INTO prediction_run_projection (prediction_run_id, answer_changes) VALUES (answer.prediction_run_id, 1)
    ON CONFLICT (prediction_run_id) DO UPDATE SET answer_changes = prediction_run_projection.answer_changes + 1;
    SELECT schema_version_id INTO version_id FROM prediction_result WHERE id = answer.prediction_result_id;
    IF TG_OP = 'DELETE' AND (EXISTS (SELECT 1 FROM purge_job_version WHERE schema_version_id = version_id)
            OR (answer.schema_review_id IS NOT NULL
                AND NOT EXISTS (SELECT 1 FROM schema_review WHERE id = answer.schema_review_id))) THEN
        RETURN NULL;
    END IF;
    IF actor IS NULL THEN
        RAISE EXCEPTION 'Removing an answer names who removes it: violates check constraint "ck_feedback_revision_actor"' USING ERRCODE = 'check_violation',
            CONSTRAINT = 'ck_feedback_revision_actor', TABLE = 'prediction_result_feedback';
    END IF;
    INSERT INTO prediction_result_feedback_revision (feedback_id, prediction_result_id, schema_version_id,
        schema_review_id, author_principal_id, feedback_type, question_index, data_value, change_kind,
        changed_by_principal_id, changed_at)
    VALUES (answer.id, answer.prediction_result_id, version_id, answer.schema_review_id, answer.created_by_principal_id,
        answer.feedback_type, answer.question_index, CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE answer.data_value END,
        CASE TG_OP WHEN 'INSERT' THEN 'CREATED' WHEN 'UPDATE' THEN 'UPDATED' ELSE 'DELETED' END, actor, now());
    RETURN NULL;
END $$;
CREATE TRIGGER trg_result_feedback_changed AFTER INSERT OR UPDATE OR DELETE ON prediction_result_feedback
    FOR EACH ROW EXECUTE FUNCTION result_feedback_changed();

CREATE TRIGGER trg_schema_review_not_purging BEFORE INSERT ON schema_review FOR EACH ROW
    EXECUTE FUNCTION refuse_under_purge('schema', 'schema_id');

-- ================================================================================================
-- API access
-- ================================================================================================

-- Outside software runs an organization's models as one of its API clients. A client holds any
-- number of keys, so a key can be replaced without stopping its software, and may run the
-- bookmarks it was given access to, public or not. Every call a key makes is kept in api_request:
-- it meters the client, feeds the organization's and the platform's views, and ties a call to the
-- run it made. A client is suspended only by the platform, with the reason its organization is
-- shown. A client is a principal: the runs it makes name it as their author.
CREATE TABLE api_client (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_api_client PRIMARY KEY,
    organization_id BIGINT NOT NULL CONSTRAINT fk_api_client_organization REFERENCES organization (id),
    name VARCHAR(80) NOT NULL CONSTRAINT ck_api_client_name_present CHECK (btrim(name) <> ''),
    description VARCHAR(400),
    status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE' CONSTRAINT ck_api_client_status CHECK (status IN ('ACTIVE', 'SUSPENDED')),
    suspension_reason VARCHAR(400),
    suspended_at TIMESTAMPTZ,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_api_client_created_by REFERENCES principal (id),
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_api_client_updated_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT ck_api_client_suspension CHECK ((status = 'SUSPENDED') = (suspended_at IS NOT NULL)),
    CONSTRAINT ck_api_client_suspension_reason CHECK (status = 'SUSPENDED' OR suspension_reason IS NULL),
    CONSTRAINT uq_api_client_org_id UNIQUE (organization_id, id));

CREATE UNIQUE INDEX uq_api_client_organization_name ON api_client (organization_id, lower(name));

ALTER TABLE principal ADD CONSTRAINT fk_principal_api_client
    FOREIGN KEY (api_client_id) REFERENCES api_client (id) ON DELETE SET NULL;

CREATE FUNCTION api_client_is_a_principal() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO principal (kind, api_client_id) VALUES ('API_CLIENT', NEW.id);
    RETURN NEW;
END $$;
CREATE TRIGGER trg_api_client_principal AFTER INSERT ON api_client FOR EACH ROW EXECUTE FUNCTION api_client_is_a_principal();

CREATE FUNCTION api_client_leaves_its_principal() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE principal SET former_label = OLD.name WHERE api_client_id = OLD.id;
    RETURN OLD;
END $$;
CREATE TRIGGER trg_api_client_principal_label BEFORE DELETE ON api_client FOR EACH ROW EXECUTE FUNCTION api_client_leaves_its_principal();

-- Only the secret's SHA-256 is kept, with its first characters to tell keys apart. Revoking a key
-- deletes it.
CREATE TABLE api_client_key (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_api_client_key PRIMARY KEY,
    api_client_id BIGINT NOT NULL CONSTRAINT fk_api_client_key_client REFERENCES api_client (id) ON DELETE CASCADE,
    name VARCHAR(80) NOT NULL CONSTRAINT ck_api_client_key_name_present CHECK (btrim(name) <> ''),
    key_prefix VARCHAR(16) NOT NULL,
    key_hash VARCHAR(64) NOT NULL CONSTRAINT uq_api_client_key_hash UNIQUE
        CONSTRAINT ck_api_client_key_hash CHECK (key_hash ~ '^[0-9a-f]{64}$'),
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_api_client_key_created_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    last_used_at TIMESTAMPTZ);

CREATE INDEX idx_api_client_key_client ON api_client_key (api_client_id);

-- A bookmark a client may run, granted by a member. A client runs only its own organization's
-- bookmarks: the row carries the client's organization and the bookmark's schema, which must be
-- that organization's.
CREATE TABLE api_client_bookmark (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_api_client_bookmark PRIMARY KEY,
    organization_id BIGINT NOT NULL,
    schema_id BIGINT NOT NULL,
    api_client_id BIGINT NOT NULL,
    schema_bookmark_id BIGINT NOT NULL,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_api_client_bookmark_created_by REFERENCES principal (id),
    created_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uq_api_client_bookmark UNIQUE (api_client_id, schema_bookmark_id),
    CONSTRAINT fk_api_client_bookmark_client FOREIGN KEY (organization_id, api_client_id)
        REFERENCES api_client (organization_id, id) ON DELETE CASCADE,
    CONSTRAINT fk_api_client_bookmark_schema FOREIGN KEY (organization_id, schema_id)
        REFERENCES schema (organization_id, id),
    CONSTRAINT fk_api_client_bookmark_bookmark FOREIGN KEY (schema_id, schema_bookmark_id)
        REFERENCES schema_bookmark (schema_id, id) ON DELETE CASCADE);

CREATE INDEX idx_api_client_bookmark_bookmark ON api_client_bookmark (schema_bookmark_id);
CREATE INDEX idx_api_client_bookmark_schema ON api_client_bookmark (organization_id, schema_id);

-- One call made with a valid key, whatever its outcome: an append-only log. Like the audit log it
-- outlives what it names, so the client, key, bookmark and run are plain ids beside the names they
-- had; the organization's month is counted here, so deleting a client does not give its calls back,
-- and only a purge of the organization removes its calls.
CREATE TABLE api_request (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_api_request PRIMARY KEY,
    request_id UUID NOT NULL CONSTRAINT uq_api_request_request_id UNIQUE,
    organization_id BIGINT NOT NULL CONSTRAINT fk_api_request_organization REFERENCES organization (id),
    api_client_id BIGINT,
    client_name VARCHAR(80) NOT NULL,
    api_client_key_id BIGINT,
    key_prefix VARCHAR(16) NOT NULL,
    schema_bookmark_id BIGINT,
    bookmark_name VARCHAR(180),
    prediction_run_id BIGINT,
    http_status INTEGER NOT NULL CONSTRAINT ck_api_request_http_status CHECK (http_status BETWEEN 100 AND 599),
    error_code VARCHAR(40),
    duration_ms INTEGER NOT NULL CONSTRAINT ck_api_request_duration CHECK (duration_ms >= 0),
    created_at TIMESTAMPTZ NOT NULL);

CREATE INDEX idx_api_request_organization_created ON api_request (organization_id, created_at DESC);
CREATE INDEX idx_api_request_client_created ON api_request (api_client_id, created_at DESC);
-- The log is append-only, so its creation order is its physical order: retention reads a range.
CREATE INDEX idx_api_request_created ON api_request USING BRIN (created_at);

-- An API run's client is one of the run's organization; the run outlives it.
ALTER TABLE prediction_run ADD CONSTRAINT fk_prediction_run_api_client FOREIGN KEY (organization_id, api_client_id)
    REFERENCES api_client (organization_id, id) ON DELETE SET NULL (api_client_id);
CREATE INDEX idx_prediction_run_api_client ON prediction_run (organization_id, api_client_id) WHERE api_client_id IS NOT NULL;

CREATE TRIGGER trg_api_client_not_purging BEFORE INSERT ON api_client FOR EACH ROW
    EXECUTE FUNCTION refuse_under_purge('organization', 'organization_id');
CREATE TRIGGER trg_api_client_bookmark_not_purging BEFORE INSERT ON api_client_bookmark FOR EACH ROW
    EXECUTE FUNCTION refuse_under_purge('schema', 'schema_id');

-- ================================================================================================
-- Operations
-- ================================================================================================

-- What the platform keeps about running itself: the audit log, notifications, alerts, the queues
-- of storage deletions and purges, and open terminal sessions.

-- The audit log records every action, by people, API clients and the system. Its actor is a
-- principal, which outlives the account; a visitor, someone who failed to sign in, or an account
-- already gone when the entry is written is none, and is named by its label alone. An entry never
-- stops the action it records. An entry outlives the organization it names, so it
-- keeps the organization's id without a foreign key, and the names as they were when it was
-- written.
CREATE TABLE audit_event (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_audit_event PRIMARY KEY,
    organization_id BIGINT,
    organization_label VARCHAR(255),
    actor_kind VARCHAR(20) NOT NULL CONSTRAINT ck_audit_actor_kind CHECK (actor_kind IN ('USER', 'SYSTEM', 'API_CLIENT', 'VISITOR')),
    actor_principal_id BIGINT,
    actor_label VARCHAR(255) NOT NULL,
    action VARCHAR(120) NOT NULL,
    target_type VARCHAR(80) NOT NULL,
    target_id VARCHAR(120),
    metadata JSONB,
    ip INET,
    request_id UUID,
    created_at TIMESTAMPTZ NOT NULL,
    -- The actor's kind is its principal's, when the event names one.
    CONSTRAINT fk_audit_event_actor FOREIGN KEY (actor_principal_id, actor_kind) REFERENCES principal (id, kind));

CREATE INDEX idx_audit_event_catalog ON audit_event (organization_id, created_at DESC, id DESC);
CREATE INDEX idx_audit_event_created ON audit_event (created_at DESC, id DESC);

-- What happened in the background, told to the person who asked for it. A notification outlives
-- what it describes, so it references neither its organization nor its target: the payload keeps
-- the labels that draw it, and the organization is null for one about the platform itself.
CREATE TABLE notification (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_notification PRIMARY KEY,
    recipient_user_id BIGINT NOT NULL CONSTRAINT fk_notification_recipient REFERENCES app_user (id) ON DELETE CASCADE,
    organization_id BIGINT,
    -- What it is about follows from what happened.
    kind VARCHAR(64) NOT NULL,
    target_type VARCHAR(32) NOT NULL,
    CONSTRAINT ck_notification_kind CHECK (CASE target_type
        WHEN 'PREDICTION_JOB' THEN kind IN ('PREDICTION_JOB_COMPLETED', 'PREDICTION_JOB_COMPLETED_WITH_FAILURES', 'PREDICTION_JOB_STOPPED', 'PREDICTION_JOB_CANCELLED')
        WHEN 'MODEL' THEN kind IN ('MODEL_READY', 'MODEL_FAILED')
        WHEN 'INVITATION' THEN kind IN ('INVITATION_RECEIVED', 'INVITATION_ACCEPTED', 'INVITATION_DECLINED')
        WHEN 'ORGANIZATION' THEN kind IN ('ORGANIZATION_JOINED', 'ORGANIZATION_PURGED')
        WHEN 'REVIEW' THEN kind IN ('REVIEW_ASSIGNED', 'REVIEW_REOPENED')
        WHEN 'PURGE_JOB' THEN kind IN ('PURGE_COMPLETED', 'PURGE_FAILED')
        WHEN 'SYSTEM_ALERT' THEN kind IN ('SYSTEM_ALERT_RAISED', 'SYSTEM_ALERT_ESCALATED', 'SYSTEM_ALERT_RESOLVED')
        WHEN 'BOOKMARK' THEN kind IN ('BOOKMARK_UNPUBLISHED')
        ELSE false END),
    target_id VARCHAR(120) NOT NULL,
    payload JSONB NOT NULL,
    read_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL);

CREATE INDEX idx_notification_recipient ON notification (recipient_user_id, id DESC);
CREATE INDEX idx_notification_unread ON notification (recipient_user_id, id DESC) WHERE read_at IS NULL;
CREATE INDEX idx_notification_read_at ON notification (read_at) WHERE read_at IS NOT NULL;

-- What the platform warned its superadmins about its own load. The partial unique index keeps one
-- alert open per signal, whichever API instance raises it. trigger_value and threshold are what put
-- the alert at its severity; held_at is when any instance last saw the condition stand, which is
-- what lets it resolve only after a quiet period seen by all of them. Resolved alerts are pruned.
CREATE TABLE system_alert (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_system_alert PRIMARY KEY,
    signal VARCHAR(64) NOT NULL,
    severity VARCHAR(16) NOT NULL CONSTRAINT ck_system_alert_severity CHECK (severity IN ('WARNING', 'CRITICAL')),
    trigger_value DOUBLE PRECISION NOT NULL,
    threshold DOUBLE PRECISION NOT NULL,
    latest_value DOUBLE PRECISION NOT NULL,
    raised_at TIMESTAMPTZ NOT NULL,
    held_at TIMESTAMPTZ NOT NULL,
    resolved_at TIMESTAMPTZ);

CREATE UNIQUE INDEX uq_system_alert_open ON system_alert (signal) WHERE resolved_at IS NULL;
CREATE INDEX idx_system_alert_resolved ON system_alert (resolved_at DESC) WHERE resolved_at IS NOT NULL;

-- Objects to remove from storage once nothing refers to them; workers claim a row under a lease.
-- One task per stored version of an object, or one with no version for every version of a key.
-- organization_id is which organization a deletion belongs to, for the entry that reports it
-- failing for good.
CREATE TABLE storage_deletion_task (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_storage_deletion_task PRIMARY KEY,
    organization_id BIGINT,
    storage_bucket VARCHAR(100) NOT NULL,
    storage_object_key VARCHAR(512) NOT NULL,
    storage_version_id VARCHAR(255),
    status VARCHAR(32) NOT NULL DEFAULT 'PENDING'
        CONSTRAINT ck_storage_deletion_status CHECK (status IN ('PENDING', 'RUNNING', 'COMPLETED', 'FAILED')),
    attempts INTEGER NOT NULL DEFAULT 0 CONSTRAINT ck_storage_deletion_attempts CHECK (attempts >= 0),
    next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    error_message TEXT,
    lease_expires_at TIMESTAMPTZ,
    lease_owner VARCHAR(128),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMPTZ,
    CONSTRAINT uq_storage_deletion_object UNIQUE NULLS NOT DISTINCT (storage_bucket, storage_object_key, storage_version_id),
    CONSTRAINT ck_storage_deletion_claim CHECK ((status = 'RUNNING') = (lease_owner IS NOT NULL)
        AND (lease_owner IS NULL) = (lease_expires_at IS NULL)),
    CONSTRAINT ck_storage_deletion_completed CHECK ((status = 'COMPLETED') = (completed_at IS NOT NULL)),
    CONSTRAINT ck_storage_deletion_failed CHECK (status <> 'FAILED' OR error_message IS NOT NULL));

CREATE INDEX idx_storage_deletion_pending ON storage_deletion_task (next_attempt_at, id) WHERE status = 'PENDING';
CREATE INDEX idx_storage_deletion_lease ON storage_deletion_task (lease_expires_at, id) WHERE status = 'RUNNING';
CREATE INDEX idx_storage_deletion_completed ON storage_deletion_task (completed_at) WHERE status = 'COMPLETED';

-- A superadmin's cascade purge, run on the server like a bulk job: workers claim a job with
-- SELECT ... FOR UPDATE SKIP LOCKED under a lease, delete in small transactions and write down the
-- phase they reached, so a job whose worker crashed is claimed again and goes on from there. A
-- failed purge keeps its target closed until it is retried. A job outlives what it names, so it
-- references its target by plain id; who asked for it is a principal, which outlives them too.
CREATE TABLE purge_job (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_purge_job PRIMARY KEY,
    scope VARCHAR(16) NOT NULL CONSTRAINT ck_purge_job_scope CHECK (scope IN ('ORGANIZATION', 'USER', 'SCHEMA', 'MODEL')),
    target_id BIGINT NOT NULL,
    target_label VARCHAR(255) NOT NULL,
    -- The organization the job deletes, or the target lives in; for a user, their personal account.
    organization_id BIGINT NOT NULL,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_purge_job_created_by REFERENCES principal (id),
    -- Who asked last: the requester, or the superadmin who retried it.
    updated_by_principal_id BIGINT NOT NULL CONSTRAINT fk_purge_job_updated_by REFERENCES principal (id),
    status VARCHAR(16) NOT NULL CONSTRAINT ck_purge_job_status CHECK (status IN ('QUEUED', 'RUNNING', 'COMPLETED', 'FAILED')),
    phase VARCHAR(32) NOT NULL CONSTRAINT ck_purge_job_phase CHECK (phase IN (
        'PREPARE', 'JOBS', 'FEEDBACK', 'REVIEWS', 'RESULTS', 'RUNS', 'SCHEMA_CONTENT',
        'VERSIONS', 'MODELS', 'PLUGINS', 'MEMBERS', 'ACCOUNT', 'FINISH')),
    counts JSONB NOT NULL DEFAULT '{}'::jsonb,
    error_message TEXT,
    lease_owner VARCHAR(128),
    lease_expires_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    finished_at TIMESTAMPTZ,
    CONSTRAINT ck_purge_job_lease CHECK ((lease_owner IS NULL) = (lease_expires_at IS NULL)
        AND (status = 'RUNNING') = (lease_owner IS NOT NULL)),
    CONSTRAINT ck_purge_job_finished CHECK ((finished_at IS NOT NULL) = (status IN ('COMPLETED', 'FAILED'))),
    CONSTRAINT ck_purge_job_error CHECK ((status = 'FAILED') = (error_message IS NOT NULL)));

CREATE UNIQUE INDEX uq_purge_job_open ON purge_job (scope, target_id) WHERE status <> 'COMPLETED';
CREATE INDEX idx_purge_job_claim ON purge_job (id) WHERE status IN ('QUEUED', 'RUNNING');

-- The snapshots a job destroys, fixed when it starts: a phase that removes what chose them cannot
-- lose the rest, and every later phase reads the same set.
CREATE TABLE purge_job_version (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_purge_job_version PRIMARY KEY,
    purge_job_id BIGINT NOT NULL CONSTRAINT fk_purge_job_version_job REFERENCES purge_job (id) ON DELETE CASCADE,
    schema_version_id BIGINT NOT NULL,
    CONSTRAINT uq_purge_job_version UNIQUE (purge_job_id, schema_version_id));

CREATE INDEX idx_purge_job_version_version ON purge_job_version (schema_version_id);

-- A job lists only snapshots of its target, while it runs: listing one is what lets the purge remove
-- its bindings, results and answers.
CREATE FUNCTION purge_job_version_is_its_target() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM purge_job j JOIN schema_version v ON v.id = NEW.schema_version_id
            WHERE j.id = NEW.purge_job_id AND j.status = 'RUNNING' AND v.organization_id = j.organization_id
                AND (j.scope <> 'SCHEMA' OR v.schema_id = j.target_id)
                AND (j.scope <> 'MODEL' OR EXISTS (SELECT 1 FROM schema_model_binding b
                    WHERE b.schema_version_id = v.id AND b.model_id = j.target_id))) THEN
        RAISE EXCEPTION 'A purge lists only the snapshots it destroys: violates check constraint "ck_purge_job_version_target"' USING ERRCODE = 'check_violation',
            CONSTRAINT = 'ck_purge_job_version_target', TABLE = 'purge_job_version';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER trg_purge_job_version_target BEFORE INSERT ON purge_job_version FOR EACH ROW
    EXECUTE FUNCTION purge_job_version_is_its_target();

-- The terminal sessions the API opened that have not ended yet, by the id the terminal service gave
-- them. A session leaves this table once, however it ends (closed, its browser gone, or ended by the
-- ops agent), and that is when its end is audited, so every opened session has exactly one close.
CREATE TABLE terminal_session (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT pk_terminal_session PRIMARY KEY,
    session_key VARCHAR(64) NOT NULL CONSTRAINT uq_terminal_session_key UNIQUE,
    created_by_principal_id BIGINT NOT NULL CONSTRAINT fk_terminal_session_created_by REFERENCES principal (id),
    service_name VARCHAR(120) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now());
